import itertools
import random

# Let's try to construct a graph with girth >= 7, 3-colorable, 19 vertices, >= 26 edges

# First, let's try a random search with cycle checking

def has_short_cycles(adj, max_cycle_len=6):
    """Check if graph has cycles of length <= max_cycle_len"""
    n = len(adj)
    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS
        parent = [-1] * n
        dist = [-1] * n
        dist[start] = 0
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u] and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_cycle_len:
                        return True, cycle_len
        # Also need to check for cycles that don't go through start in the BFS tree
        # Actually the above catches all cycles because any cycle has a first-visited vertex
    return False, None

def is_3_colorable(adj):
    """Check if graph is 3-colorable using backtracking"""
    n = len(adj)
    colors = [-1] * n

    def dfs(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(v + 1):
                    return True
                colors[v] = -1
        return False

    return dfs(0)

